#[must_use]
pub fn secret_at(&self, file: &Path) -> Option<&str> {
    self.attempts.iter().find_map(|a| {
        a.secret.iter().find_map(|name| {
            let path = a.artifacts.get(name)?;
            let path = path.canonicalize().unwrap_or_else(|_| path.clone());
            (path == file).then_some(name.as_str())
        })
    })
}

/// The indexes of the ledger's operations recovery still has to
/// resolve.
#[must_use]
pub fn unsettled(&self) -> Vec<usize> {
    self.unsettled_where(|_| true)
}

/// `unsettled`, launches only: what parking and closing wait on,
/// since a launch still in flight would bring up a session after
/// they stopped everything.
#[must_use]
pub fn unsettled_creations(&self) -> Vec<usize> {
    self.unsettled_where(|o| o.class == "creation")
}

fn unsettled_where(&self, keep: impl Fn(&Operation) -> bool) -> Vec<usize> {
    self.ledger
        .iter()
        .enumerate()
        .filter(|(_, o)| keep(o) && o.unresolved())
        .map(|(i, _)| i)
        .collect()
}

/// The attempts of stage `stage`, latest numbers last.
pub fn attempts_of<'a>(&'a self, stage: &'a str) -> impl Iterator<Item = &'a Attempt> + 'a {
    self.attempts.iter().filter(move |a| a.stage == stage)
}

/// The most recent completed attempt of any stage that wrote `name`.
#[must_use]
pub fn input(&self, name: &str) -> Option<&PathBuf> {
    self.input_with_stage(name).map(|(_, path)| path)
}

/// The same, with the stage whose attempt wrote it: a reader is told
/// whose notes these are when a later stage wrote none.
#[must_use]
pub fn input_with_stage(&self, name: &str) -> Option<(&str, &PathBuf)> {
    self.input_where(name, |_| true)
}

/// The most recent completed attempt that wrote `name` among those
/// `keep` accepts, with its stage: a lane's reader keeps only the
/// attempts it can see.
#[must_use]
pub fn input_where(
    &self,
    name: &str,
    keep: impl Fn(&Attempt) -> bool,
) -> Option<(&str, &PathBuf)> {
    self.attempts
        .iter()
        .rev()
        .filter(|a| a.state == AttemptState::Complete && !a.forgotten.contains_key(name))
        .filter(|a| keep(a))
        .find_map(|a| a.artifacts.get(name).map(|p| (a.stage.as_str(), p)))
}

/// `shown_where` with no filter.
#[must_use]
pub fn shown(&self, name: &str) -> Option<(&Attempt, &PathBuf)> {
    self.shown_where(name, |_| true)
}

/// `input_where` for a reader who wants the document as it stands: a
/// workflow attempt still open counts too, since a review edits its
/// copy in place until `finalize` is answered. Display only; an agent
/// is handed `input_where`'s complete files.
#[must_use]
pub fn shown_where(
    &self,
    name: &str,
    keep: impl Fn(&Attempt) -> bool,
) -> Option<(&Attempt, &PathBuf)> {
    self.attempts
        .iter()
        .rev()
        .filter(|a| !a.forgotten.contains_key(name))
        .filter(|a| {
            a.state == AttemptState::Complete
                || (a.kind == AttemptKind::Workflow && a.is_open())
        })
        .filter(|a| keep(a))
        .find_map(|a| a.artifacts.get(name).map(|p| (a, p)))
}

#[must_use]
pub fn pending_decisions(&self) -> Vec<&Decision> {
    self.decisions.iter().filter(|d| d.pending()).collect()
}

/// The pending decisions that wait on the user and count against
/// the project's limit: while the ticket is closing, only a `stuck`
/// question, which the close waits on; its other pending decisions
/// are on their way to cancelled. Every count and every view reads
/// this, so the rule lives in one place.
#[must_use]
pub fn waiting_on_you(&self) -> Vec<&Decision> {
    let closing = matches!(self.state, TicketState::Closing { .. });
    self.pending_decisions()
        .into_iter()
        .filter(|d| !closing || d.name == STUCK)
        .collect()
}

/// The session a card for this ticket should show: the latest
/// attempt's, or none.
#[must_use]
pub fn current_session(&self) -> Option<&String> {
    self.attempts.iter().rev().find_map(|a| a.session.as_ref())
}

#[must_use]
pub fn active(&self) -> bool {
    self.state == TicketState::Active
}

/// Whether `close` would start a close, as far as the record says:
/// parked, or active with nothing open. A tree with changes is
/// still refused when the close runs; that needs git to tell.
#[must_use]
pub fn closable(&self) -> bool {
    match self.state {
        TicketState::Parked { .. } => true,
        if !t.active() {
            return Ok(());
        }
    }
    if all_complete {
        self.advance(t, now_ms)?;
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn start_workflow(
    &mut self,
    t: &mut Ticket,
    ps: &mut ProjectState,
    p: &Pipeline,
    stage: &Stage,
    ctx: &str,
    lane: Option<&str>,
    n: u32,
    now_ms: u64,
) -> Result<()> {
    let reviewer_name = stage.review.clone().unwrap_or_default();
    let operator = p.operators.get(&reviewer_name);
    let Some(review) = operator.and_then(|o| o.review.clone()) else {
        return self.park(
            t,
            ps,
            &format!("stage {} names no reviewer", stage.name),
            now_ms,
        );
    };
    let Some(subject) = stage.subject.clone() else {
        return self.park(
            t,
            ps,
            &format!("stage {} names no subject", stage.name),
            now_ms,
        );
    };
    let (source_path, source_session) = match review_subject(t, &subject) {
        Ok(found) => found,
        Err(why) => return self.park(t, ps, &format!("stage {}: {why}", stage.name), now_ms),
    };
    let dir = self.attempt_dir(t, &stage.name, n, ctx)?;
    let copy = dir.join(format!("{subject}.md"));
    std::fs::copy(&source_path, &copy)
        .with_context(|| format!("copy {} to {}", source_path.display(), copy.display()))?;
    // The reviewer's feedback lives beside the copy, in Dispatch's
    // directory. A reviewer that can be told to write there runs in
    // the ticket's tree, with the code and the trust the earlier
    // agents already granted; one that can only write in its cwd
    // runs in the attempt directory and is told where the tree is.
    let mut reviewer_args = operator.map(|o| o.args.clone()).unwrap_or_default();
    let reviewer_cwd = match primary_tree(t, p) {
        Some(tree) if review.reviewer.reviews_in_tree() => {
            reviewer_args.extend(review.reviewer.write_flags(&dir));
            tree
        }
        _ => dir.clone(),
    };
    let definition = definition_of(&reviewer_name, review, &vars_for(t, p, lane));
    t.attempts.push(new_attempt(
        &stage.name,
        n,
        ctx,
        AttemptKind::Workflow,
        AttemptState::Starting,
        BTreeMap::from([(subject.clone(), copy.clone())]),
        now_ms,
    ));
    let name = definition.name.clone();
    self.send(
        t,
        ps,
        Some((stage.name.clone(), n)),
        "definition",
        Body::DefinitionInstall { definition },
        now_ms,
    )?;
    let reply = self.send(
        t,
        ps,
        Some((stage.name.clone(), n)),
        "run",
        Body::WorkflowStart {
            source: source_session,
            plan: copy,
            definition: name,
            reviewer_cwd: Some(reviewer_cwd),
            reviewer_args,
        },
        now_ms,
    )?;
    if let Reply::Failed { reason } = reply {
        self.fail_attempt(
            t,
            ps,
            &stage.name,
            n,
            &format!("could not start the review: {reason}"),
            now_ms,
        )?;
    }
    Ok(())
}

