            text: e.text.clone(),
            attempt: e.attempt.clone(),
            decision: e.decision.clone(),
            head: e.head.clone(),
            url: e.url.clone(),
        })
        .collect();
    Ok(EventsView {
        events,
        last,
        withdrawn,
    })
}

